window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ceeb9fcbb280d5bc"]={"versions": [{"id": "FIG-ceeb9fcbb280d5bc", "releases": ["R17-03_R1.1.0", "R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methodologie-Aktivitätsdiagramm (AUTOSAR-Workflow) zur Definition von Service Interfaces innerhalb der Entwurfsphase der AUTOSAR Adaptive Platform (AP). Das Diagramm beschreibt den Datenfluss und die Transformationsschritte von standardisierten Basispaketen über Datentypen hin zu Service-Interface-Beschreibungen und Interface-Mappings.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält folgende Entitäten, Artefakte und Aktivitäten:</p>\n<ul class=\"fig-list\"><li><strong>Artefakte / Work Products:</strong>\n<ul class=\"fig-list\"><li><code>Autosar AP Standard Package</code> (Paket-/Briefumschlagsymbol mit Schnittstellenperforation): Vordefiniertes Standardpaket der Adaptive Platform.\n</li><li><code>AP Data Types</code> (Dokumentsymbol): Spezifikation der Datentypen für die Adaptive Platform.\n</li><li><code>Service Interface Description</code> (Paket-/Briefumschlagsymbol mit Schnittstellenperforation): Beschreibung der definierten und aggregierten Service-Schnittstellen.\n</li><li><code>Service Interface Mapping</code> (Paket-/Briefumschlagsymbol mit Schnittstellenperforation): Mappings der Service-Interfaces.\n</li></ul>\n</li><li><strong>Aktivitäten / Tasks (Prozesspfeile):</strong>\n<ul class=\"fig-list\"><li><code>Provide Data Types for Adaptive Platform</code>: Bereitstellung bzw. Spezifikation von Datentypen.\n</li><li><code>Define Service Interfaces</code>: Erstellung initialer Service-Interfaces auf Basis der Datentypen.\n</li><li><code>Aggregate Service Interfaces</code>: Konsolidierung und Aggregation von Service-Interfaces sowie Erzeugung zugehöriger Mappings.\n</li></ul>\n</li><li><strong>Kardinalitäten und Stereotypen:</strong>\n<ul class=\"fig-list\"><li><code>Autosar AP Standard Package</code> $\\xrightarrow{0..1\\text{ «input»}}$ <code>Provide Data Types for Adaptive Platform</code>\n</li><li><code>Provide Data Types for Adaptive Platform</code> $\\xrightarrow{\\text{«output» } 1..*}$ <code>AP Data Types</code>\n</li><li><code>AP Data Types</code> $\\xrightarrow{1..*\\text{ «input»}}$ <code>Define Service Interfaces</code>\n</li><li><code>Define Service Interfaces</code> $\\xrightarrow{\\text{«output» } 1..*}$ <code>Service Interface Description</code>\n</li><li><code>Aggregate Service Interfaces</code> interagiert bidirektional mit <code>Service Interface Description</code>: $\\xleftarrow{\\text{«input» } 0..<em>}$ und $\\xrightarrow{\\text{«output» } 0..</em>}$\n</li><li><code>Aggregate Service Interfaces</code> $\\xrightarrow{\\text{«output» } 0..*}$ <code>Service Interface Mapping</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Workflow vollzieht sich in einer dreistufigen Sequenz:</p>\n<ol class=\"fig-list\"><li><strong>Datentyp-Bereitstellung:</strong> Die Aktivität <code>Provide Data Types for Adaptive Platform</code> nimmt optional ein <code>Autosar AP Standard Package</code> (0..1) entgegen und erzeugt mindestens eine <code>AP Data Types</code>-Beschreibung (1..*).\n</li><li><strong>Interface-Definition:</strong> Unter Verwendung von mindestens einer Datentyp-Spezifikation (1..* als Input) erzeugt die Aktivität <code>Define Service Interfaces</code> eine oder mehrere <code>Service Interface Description</code>-Artefakte (1..*).\n</li><li><strong>Interface-Aggregation &amp; Mapping:</strong> Die Aktivität <code>Aggregate Service Interfaces</code> liest optional bestehende Beschreibungen (<code>Service Interface Description</code>, 0..<em>), erzeugt oder aktualisiert Service-Interface-Beschreibungen (0..</em>) und generiert optional zugehörige <code>Service Interface Mapping</code>-Artefakte (0..*).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindender Methodenablauf für AUTOSAR AP Modellierer und Tool-Hersteller:</p>\n<ul class=\"fig-list\"><li>Datentypen (<code>AP Data Types</code>) sind eine zwingende Voraussetzung (Multiplizität 1..*) für das Definieren von Service Interfaces.\n</li><li>Die Aggregation von Service Interfaces kann iterativ auf bestehenden Beschreibungen aufsetzen (0..* Input/Output) und bildet die Grundlage für nachgelagerte Interface-Mappings (<code>Service Interface Mapping</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-cba0c69be3f70774", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methodologie-Aktivitätsdiagramm (AUTOSAR-Workflow) zur Definition von Service Interfaces innerhalb der Entwurfsphase der AUTOSAR Adaptive Platform (AP). Das Diagramm beschreibt den Datenfluss und die Transformationsschritte von standardisierten Basispaketen über Datentypen hin zu Service-Interface-Beschreibungen und Interface-Mappings.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält folgende Entitäten, Artefakte und Aktivitäten:</p>\n<ul class=\"fig-list\"><li><strong>Artefakte / Work Products:</strong>\n<ul class=\"fig-list\"><li><code>Autosar AP Standard Package</code> (Paket-/Briefumschlagsymbol mit Schnittstellenperforation): Vordefiniertes Standardpaket der Adaptive Platform.\n</li><li><code>AP Data Types</code> (Dokumentsymbol): Spezifikation der Datentypen für die Adaptive Platform.\n</li><li><code>Service Interface Description</code> (Paket-/Briefumschlagsymbol mit Schnittstellenperforation): Beschreibung der definierten und aggregierten Service-Schnittstellen.\n</li><li><code>Service Interface Mapping</code> (Paket-/Briefumschlagsymbol mit Schnittstellenperforation): Mappings der Service-Interfaces.\n</li></ul>\n</li><li><strong>Aktivitäten / Tasks (Prozesspfeile):</strong>\n<ul class=\"fig-list\"><li><code>Select or define Data Types for Adaptive Platform</code>: Auswahl oder Neudefinition von Datentypen.\n</li><li><code>Define Service Interfaces</code>: Erstellung initialer Service-Interfaces auf Basis der Datentypen.\n</li><li><code>Aggregate Service Interfaces</code>: Konsolidierung und Aggregation von Service-Interfaces sowie Erzeugung zugehöriger Mappings.\n</li></ul>\n</li><li><strong>Kardinalitäten und Stereotypen:</strong>\n<ul class=\"fig-list\"><li><code>Autosar AP Standard Package</code> $\\xrightarrow{0..1\\text{ «input»}}$ <code>Select or define Data Types for Adaptive Platform</code>\n</li><li><code>Select or define Data Types for Adaptive Platform</code> $\\xrightarrow{\\text{«output» } 1..*}$ <code>AP Data Types</code>\n</li><li><code>AP Data Types</code> $\\xrightarrow{1..*\\text{ «input»}}$ <code>Define Service Interfaces</code>\n</li><li><code>Define Service Interfaces</code> $\\xrightarrow{\\text{«output» } 1..*}$ <code>Service Interface Description</code>\n</li><li><code>Aggregate Service Interfaces</code> interagiert bidirektional mit <code>Service Interface Description</code>: $\\xleftarrow{\\text{«input» } 0..<em>}$ und $\\xrightarrow{\\text{«output» } 0..</em>}$\n</li><li><code>Aggregate Service Interfaces</code> $\\xrightarrow{\\text{«output» } 0..*}$ <code>Service Interface Mapping</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Workflow vollzieht sich in einer dreistufigen Sequenz:</p>\n<ol class=\"fig-list\"><li><strong>Datentyp-Auswahl/Definition:</strong> Die Aktivität <code>Select or define Data Types for Adaptive Platform</code> nimmt optional ein <code>Autosar AP Standard Package</code> (0..1) entgegen und erzeugt mindestens eine <code>AP Data Types</code>-Beschreibung (1..*).\n</li><li><strong>Interface-Definition:</strong> Unter Verwendung von mindestens einer Datentyp-Spezifikation (1..* als Input) erzeugt die Aktivität <code>Define Service Interfaces</code> eine oder mehrere <code>Service Interface Description</code>-Artefakte (1..*).\n</li><li><strong>Interface-Aggregation &amp; Mapping:</strong> Die Aktivität <code>Aggregate Service Interfaces</code> liest optional bestehende Beschreibungen (<code>Service Interface Description</code>, 0..<em>), erzeugt oder aktualisiert Service-Interface-Beschreibungen (0..</em>) und generiert optional zugehörige <code>Service Interface Mapping</code>-Artefakte (0..*).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindender Methodenablauf für AUTOSAR AP Modellierer und Tool-Hersteller:</p>\n<ul class=\"fig-list\"><li>Datentypen (<code>AP Data Types</code>) sind eine zwingende Voraussetzung (Multiplizität 1..*) für das Definieren von Service Interfaces.\n</li><li>Die Aggregation von Service Interfaces kann iterativ auf bestehenden Beschreibungen aufsetzen (0..* Input/Output) und bildet die Grundlage für nachgelagerte Interface-Mappings (<code>Service Interface Mapping</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ba70f55020fbf960", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methodologie-Aktivitätsdiagramm (AUTOSAR-Workflow) zur Definition von Service Interfaces innerhalb der Entwurfsphase der AUTOSAR Adaptive Platform (AP). Das Diagramm beschreibt den Datenfluss und die Transformationsschritte von standardisierten Basispaketen über Datentypen hin zu Service-Interface-Beschreibungen und Interface-Mappings.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält folgende Entitäten, Artefakte und Aktivitäten:</p>\n<ul class=\"fig-list\"><li><strong>Artefakte / Work Products:</strong>\n<ul class=\"fig-list\"><li><code>Autosar AP Standard Package</code> (Paket-/Briefumschlagsymbol mit Schnittstellenperforation): Vordefiniertes Standardpaket der Adaptive Platform.\n</li><li><code>AP Data Types</code> (Dokumentsymbol): Spezifikation der Datentypen für die Adaptive Platform.\n</li><li><code>Service Interface Description</code> (Paket-/Briefumschlagsymbol mit Schnittstellenperforation): Beschreibung der definierten und aggregierten Service-Schnittstellen.\n</li><li><code>Service Interface Mapping</code> (Paket-/Briefumschlagsymbol mit Schnittstellenperforation): Mappings der Service-Interfaces.\n</li></ul>\n</li><li><strong>Aktivitäten / Tasks (Prozesspfeile):</strong>\n<ul class=\"fig-list\"><li><code>Select or define Data Types for Adaptive Platform</code>: Auswahl oder Neudefinition von Datentypen.\n</li><li><code>Define Service Interfaces</code>: Erstellung initialer Service-Interfaces auf Basis der Datentypen.\n</li><li><code>Aggregate Service Interfaces</code>: Konsolidierung und Aggregation von Service-Interfaces sowie Erzeugung zugehöriger Mappings.\n</li></ul>\n</li><li><strong>Kardinalitäten und Stereotypen:</strong>\n<ul class=\"fig-list\"><li><code>Autosar AP Standard Package</code> $\\xrightarrow{0..1\\text{ «input»}}$ <code>Select or define Data Types for Adaptive Platform</code>\n</li><li><code>Select or define Data Types for Adaptive Platform</code> $\\xrightarrow{\\text{«output» } 1..*}$ <code>AP Data Types</code>\n</li><li><code>AP Data Types</code> $\\xrightarrow{1..*\\text{ «input»}}$ <code>Define Service Interfaces</code>\n</li><li><code>Define Service Interfaces</code> $\\xrightarrow{\\text{«output» } 1..*}$ <code>Service Interface Description</code>\n</li><li><code>Aggregate Service Interfaces</code> interagiert bidirektional mit <code>Service Interface Description</code>: $\\xleftarrow{\\text{«input» } 0..<em>}$ und $\\xrightarrow{\\text{«output» } 0..</em>}$\n</li><li><code>Aggregate Service Interfaces</code> $\\xrightarrow{\\text{«output» } 0..*}$ <code>Service Interface Mapping</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Workflow vollzieht sich in einer dreistufigen Sequenz:</p>\n<ol class=\"fig-list\"><li><strong>Datentyp-Auswahl/Definition:</strong> Die Aktivität <code>Select or define Data Types for Adaptive Platform</code> nimmt optional ein <code>Autosar AP Standard Package</code> (0..1) entgegen und erzeugt mindestens eine <code>AP Data Types</code>-Beschreibung (1..*).\n</li><li><strong>Interface-Definition:</strong> Unter Verwendung von mindestens einer Datentyp-Spezifikation (1..* als Input) erzeugt die Aktivität <code>Define Service Interfaces</code> eine oder mehrere <code>Service Interface Description</code>-Artefakte (1..*).\n</li><li><strong>Interface-Aggregation &amp; Mapping:</strong> Die Aktivität <code>Aggregate Service Interfaces</code> liest optional bestehende Beschreibungen (<code>Service Interface Description</code>, 0..<em>), erzeugt oder aktualisiert Service-Interface-Beschreibungen (0..</em>) und generiert optional zugehörige <code>Service Interface Mapping</code>-Artefakte (0..*).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindender Methodenablauf für AUTOSAR AP Modellierer und Tool-Hersteller:</p>\n<ul class=\"fig-list\"><li>Datentypen (<code>AP Data Types</code>) sind eine zwingende Voraussetzung (Multiplizität 1..*) für das Definieren von Service Interfaces.\n</li><li>Die Aggregation von Service Interfaces kann iterativ auf bestehenden Beschreibungen aufsetzen (0..* Input/Output) und bildet die Grundlage für nachgelagerte Interface-Mappings (<code>Service Interface Mapping</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-ceeb9fcbb280d5bc", "to": "FIG-cba0c69be3f70774", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Aktivität <code>Provide Data Types for Adaptive Platform</code> umbenannt in <code>Select or define Data Types for Adaptive Platform</code>.\n</li></ul>"}, {"from": "FIG-cba0c69be3f70774", "to": "FIG-ba70f55020fbf960", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Diagrammlayout von vertikaler Anordnung auf zickzackförmiges Layout umgestellt: <code>Autosar AP Standard Package</code> und <code>AP Data Types</code> links angeordnet, Aktivitäten rechts bzw. mittig positioniert.\n</li><li>Pfeilverläufe und Beschriftungspositionen an das geänderte Layout angepasst.\n</li></ul>"}]};
